/** Marginal Gaussian latent-interaction likelihood; conditional analytic integration plus checked quadrature. */
public final class LatentInteractionSem {
    private LatentInteractionSem() {}
    public record Factor(String name,int[] columns) {
        public Factor { if(name==null||name.isBlank()||name.length()>120||columns==null||columns.length<3||columns.length>12||Arrays.stream(columns).anyMatch(i->i<0)||Arrays.stream(columns).distinct().count()!=columns.length)throw new IllegalArgumentException("Each reflective factor needs a name and 3–12 distinct indicators.");columns=columns.clone(); }
        @Override public int[] columns(){return columns.clone();}
    }
    public record Interaction(int first,int second) {public Interaction {if(first>second){int swap=first;first=second;second=swap;}if(first<0)throw new IllegalArgumentException("Invalid latent product.");}}
    public record Model(List<Factor> predictors,Factor outcome,List<Interaction> interactions) {
        public Model {predictors=List.copyOf(predictors);Objects.requireNonNull(outcome);interactions=List.copyOf(interactions);if(predictors.isEmpty()||predictors.size()>4||interactions.size()>10||new HashSet<>(interactions).size()!=interactions.size())throw new IllegalArgumentException("Specify 1–4 latent predictors and at most ten distinct quadratic/product terms.");Set<String> names=new HashSet<>();Set<Integer> columns=new HashSet<>();List<Factor> factors=new ArrayList<>(predictors);factors.add(outcome);for(var factor:factors){if(!names.add(factor.name()))throw new IllegalArgumentException("Latent factor names must be unique.");for(int column:factor.columns())if(!columns.add(column))throw new IllegalArgumentException("This likelihood requires disjoint reflective measurement blocks; cross-loadings are not accepted.");}for(var term:interactions)if(term.second()>=predictors.size())throw new IllegalArgumentException("Latent interaction index exceeds the predictor set.");}
    }
    public enum PredictorDistribution { NORMAL, STUDENT_T }
    public record Options(int nodes,int checkNodes,int maxIterations,int starts,double gradientTolerance,double functionTolerance,double integrationTolerance,double confidence,PredictorDistribution predictorDistribution,double predictorDegreesOfFreedom) {
        public Options {if(predictorDistribution==null){predictorDistribution=PredictorDistribution.NORMAL;if(predictorDegreesOfFreedom==0)predictorDegreesOfFreedom=7;}if(!Double.isFinite(predictorDegreesOfFreedom)||predictorDegreesOfFreedom<=4)throw new IllegalArgumentException("Predictor Student t degrees of freedom must exceed four for finite quadratic moments.");if(nodes<5||nodes>33||checkNodes<=nodes||checkNodes>49||maxIterations<10||maxIterations>10000||starts<1||starts>8||!Double.isFinite(gradientTolerance)||gradientTolerance<=0||!Double.isFinite(functionTolerance)||functionTolerance<=0||!Double.isFinite(integrationTolerance)||integrationTolerance<=0||integrationTolerance>.05)throw new IllegalArgumentException("Invalid latent likelihood optimization/quadrature settings.");Inference.confidence(confidence);}
        public Options(int nodes,int checkNodes,int maxIterations,int starts,double gradientTolerance,double functionTolerance,double integrationTolerance,double confidence){this(nodes,checkNodes,maxIterations,starts,gradientTolerance,functionTolerance,integrationTolerance,confidence,PredictorDistribution.NORMAL,7);}
        public static Options defaults(){return new Options(15,23,500,2,2e-6,1e-10,1e-3,.95);}
    }
    public record Measurement(String name,int[] columns,double[] loadings,double[] intercepts,double[] errorVariances) {
        public Measurement {columns=columns.clone();loadings=loadings.clone();intercepts=intercepts.clone();errorVariances=errorVariances.clone();}
        @Override public int[] columns(){return columns.clone();}@Override public double[] loadings(){return loadings.clone();}@Override public double[] intercepts(){return intercepts.clone();}@Override public double[] errorVariances(){return errorVariances.clone();}
    }
    public record Term(String name,double estimate,double standardError,double robustStandardError,double z,double pValue,double lower,double upper) {}
    public record Fit(Model model,Options options,int observations,int parameterCount,String dataSha256,List<Measurement> measurement,double[][] predictorCovariance,double structuralIntercept,double[] mainEffects,double[] nonlinearEffects,double residualVariance,double latentOutcomeMean,double latentOutcomeVariance,double latentRSquared,double logLikelihood,double aic,double bic,boolean converged,int iterations,String convergenceReason,int integrationDimensions,boolean integrationStable,double integrationParameterChange,double integrationLogLikelihoodChange,boolean locallyIdentified,int informationRank,double informationCondition,boolean boundarySolution,List<Term> terms,double[][] parameterCovariance,double[][] robustParameterCovariance,double[] optimizerParameters,List<String> optimizerLabels,List<String> warnings) {
        public Fit {measurement=List.copyOf(measurement);predictorCovariance=Matrices.copy(predictorCovariance);mainEffects=mainEffects.clone();nonlinearEffects=nonlinearEffects.clone();terms=List.copyOf(terms);parameterCovariance=Matrices.copy(parameterCovariance);robustParameterCovariance=Matrices.copy(robustParameterCovariance);optimizerParameters=optimizerParameters.clone();optimizerLabels=List.copyOf(optimizerLabels);warnings=List.copyOf(warnings);}
        @Override public double[][] predictorCovariance(){return Matrices.copy(predictorCovariance);}@Override public double[] mainEffects(){return mainEffects.clone();}@Override public double[] nonlinearEffects(){return nonlinearEffects.clone();}@Override public double[][] parameterCovariance(){return Matrices.copy(parameterCovariance);}@Override public double[][] robustParameterCovariance(){return Matrices.copy(robustParameterCovariance);}@Override public double[] optimizerParameters(){return optimizerParameters.clone();}
    }
    public record Resampled(Fit point,Bootstrap.Result inference) {}
    private record Grid(double[][] values,double[] logWeights) {}
    private record State(double[] loading,double[] intercept,double[] error,double[][] phi,double alpha,double[] beta,double[] gamma,double psi) {}
    private record Raw(List<Measurement> measurement,double[][] phi,double alpha,double[] beta,double[] gamma,double psi,double[] vector,List<String> labels,double mean,double variance,double rSquared) {}
    private record Information(double[][] covariance,double[][] robust,int rank,double condition,boolean identified) {}

    private static int[] integrated(Model model){int q=model.predictors().size(),bestMask=0,best=-1;for(int mask=0;mask<(1<<q);mask++){boolean valid=true;for(var term:model.interactions())if((mask&(1<<term.first()))!=0&&(mask&(1<<term.second()))!=0)valid=false;if(valid&&Integer.bitCount(mask)>best){best=Integer.bitCount(mask);bestMask=mask;}}final int analytic=bestMask;return java.util.stream.IntStream.range(0,q).filter(i->(analytic&(1<<i))==0).toArray();}
    private static Grid grid(int dimension,int nodes){if(dimension==0)return new Grid(new double[][]{new double[0]},new double[]{0});long count=1;for(int i=0;i<dimension;i++)count*=nodes;if(count>12000)throw new IllegalArgumentException("Quadrature tensor exceeds12,000 points; reduce interaction dimension or node count.");var normal=new GaussIntegratorFactory().hermite(nodes);double[][] values=new double[(int)count][dimension];double[] weights=new double[(int)count];for(int k=0;k<count;k++){int index=k;for(int j=0;j<dimension;j++){int position=index%nodes;index/=nodes;values[k][j]=Math.sqrt(2)*normal.getPoint(position);weights[k]+=Math.log(normal.getWeight(position)/Math.sqrt(Math.PI));}}return new Grid(values,weights);}
    private static RealMatrix sub(double[][] matrix,int[] rows,int[] columns){double[][] result=new double[rows.length][columns.length];for(int i=0;i<rows.length;i++)for(int j=0;j<columns.length;j++)result[i][j]=matrix[rows[i]][columns[j]];return new Array2DRowRealMatrix(result,false);}
    private static double logDet(CholeskyDecomposition decomposition){double value=0;RealMatrix l=decomposition.getL();for(int i=0;i<l.getRowDimension();i++)value+=2*Math.log(l.getEntry(i,i));return value;}
    private static final class Work {
        final Model model;final PredictorDistribution distribution;final double degrees;final String digest;final int n,p,q,px,py,k;final int[] owner,marker,loadingIndex,interceptIndex,errorIndex,integrated,analytic;final int[][] phiIndex;final int alphaIndex,psiIndex;final int[] betaIndex,gammaIndex;final double[][] data;final double[] means,scales,lower,upper;final List<String> labels=new ArrayList<>();
        Work(double[][] source,Model model){this(source,model,Options.defaults());}
        Work(double[][] source,Model model,Options options){this.model=model;distribution=options.predictorDistribution();degrees=options.predictorDegreesOfFreedom();int width=Matrices.width(source,30);q=model.predictors().size();List<Factor> factors=new ArrayList<>(model.predictors());factors.add(model.outcome());p=factors.stream().mapToInt(f->f.columns().length).sum();n=source.length;if(n>5000||n<p+5||(long)n*p>250000)throw new IllegalArgumentException("Latent likelihood requires enough complete cases and at most5,000 rows/250,000 selected cells.");double[][] selected=new double[n][p];owner=new int[p];marker=new int[q+1];int at=0;for(int j=0;j<factors.size();j++){marker[j]=at;for(int column:factors.get(j).columns()){if(column>=width)throw new IllegalArgumentException("Latent measurement column is outside the dataset.");owner[at]=j;for(int i=0;i<n;i++)selected[i][at]=source[i][column];at++;}}try{var hash=java.security.MessageDigest.getInstance("SHA-256");var buffer=java.nio.ByteBuffer.allocate(8);for(var row:selected)for(double value:row){buffer.clear();buffer.putLong(Double.doubleToLongBits(value));hash.update(buffer.array());}digest=java.util.HexFormat.of().formatHex(hash.digest());}catch(java.security.NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}px=marker[q];py=p-px;var standardized=Matrices.standardize(selected,true,false);data=standardized.values();means=standardized.means();scales=standardized.scales();loadingIndex=new int[p];interceptIndex=new int[p];errorIndex=new int[p];Arrays.fill(loadingIndex,-1);Arrays.fill(interceptIndex,-1);for(int j=0;j<p;j++)if(j!=marker[owner[j]])loadingIndex[j]=add("Loading: indicator "+j);for(int j=0;j<p;j++)if(j!=marker[q])interceptIndex[j]=add("Intercept: indicator "+j);for(int j=0;j<p;j++)errorIndex[j]=add("Log error SD: indicator "+j);phiIndex=new int[q][q];for(int a=0;a<q;a++)for(int b=0;b<=a;b++)phiIndex[a][b]=add("Predictor Cholesky "+a+","+b);alphaIndex=add("Structural intercept");betaIndex=new int[q];for(int a=0;a<q;a++)betaIndex[a]=add("Main effect: "+model.predictors().get(a).name());gammaIndex=new int[model.interactions().size()];for(int a=0;a<gammaIndex.length;a++)gammaIndex[a]=add("Product: "+model.interactions().get(a));psiIndex=add("Log structural error SD");k=labels.size();if(n<=k+2)throw new IllegalArgumentException("Use more cases than the number of free latent-model parameters.");lower=new double[k];upper=new double[k];Arrays.fill(lower,-20);Arrays.fill(upper,20);for(int i:errorIndex){lower[i]=-8;upper[i]=4;}for(int a=0;a<q;a++){lower[phiIndex[a][a]]=-8;upper[phiIndex[a][a]]=4;}lower[psiIndex]=-8;upper[psiIndex]=4;integrated=distribution==PredictorDistribution.NORMAL?LatentInteractionSem.integrated(model):java.util.stream.IntStream.range(0,q).toArray();analytic=java.util.stream.IntStream.range(0,q).filter(i->Arrays.stream(integrated).noneMatch(j->i==j)).toArray();}
        int add(String label){labels.add(label);return labels.size()-1;}
        State decode(double[] x){double[] loading=new double[p],intercept=new double[p],error=new double[p];for(int j=0;j<p;j++){loading[j]=loadingIndex[j]<0?1:x[loadingIndex[j]];intercept[j]=interceptIndex[j]<0?0:x[interceptIndex[j]];error[j]=Math.exp(2*x[errorIndex[j]]);}double[][] l=new double[q][q];for(int a=0;a<q;a++)for(int b=0;b<=a;b++)l[a][b]=a==b?Math.exp(x[phiIndex[a][b]]):x[phiIndex[a][b]];double[][] phi=new Array2DRowRealMatrix(l,false).multiply(new Array2DRowRealMatrix(l,false).transpose()).getData();double[] beta=new double[q],gamma=new double[gammaIndex.length];for(int j=0;j<q;j++)beta[j]=x[betaIndex[j]];for(int j=0;j<gamma.length;j++)gamma[j]=x[gammaIndex[j]];return new State(loading,intercept,error,phi,x[alphaIndex],beta,gamma,Math.exp(2*x[psiIndex]));}
        double[] initial(){double[] x=new double[k];for(int j=0;j<p;j++){if(loadingIndex[j]>=0)x[loadingIndex[j]]=.9;errorAt(x,j,.4);}for(int a=0;a<q;a++){x[phiIndex[a][a]]=.5*Math.log(.6);x[betaIndex[a]]=.2;}x[psiIndex]=.5*Math.log(.5);try{List<String> names=java.util.stream.IntStream.range(0,p).mapToObj(i->"V"+i).toList();List<PlsSem.Block> blocks=new ArrayList<>();List<PlsSem.Edge> edges=new ArrayList<>();List<Factor> factors=new ArrayList<>(model.predictors());factors.add(model.outcome());for(int j=0;j<factors.size();j++)blocks.add(new PlsSem.Block(factors.get(j).name(),java.util.stream.IntStream.range(marker[j],j==q?p:marker[j+1]).toArray(),PlsSem.Mode.A));for(int j=0;j<q;j++)edges.add(new PlsSem.Edge(j,q));var sem=SemModel.reflective(names,data,blocks,edges,true,false).model();var fit=CovarianceSem.fit(data,sem,new CovarianceSem.Options(300,1e-6,1e-10,CovarianceSem.Likelihood.NORMAL,false,.95));if(fit.converged()){double[][] directed=fit.directed(),disturbance=fit.disturbanceCovariance();for(int j=0;j<p;j++){if(loadingIndex[j]>=0)x[loadingIndex[j]]=directed[j][p+owner[j]];errorAt(x,j,Math.max(.02,disturbance[j][j]));}double[][] phi=new double[q][q];for(int a=0;a<q;a++)for(int b=0;b<q;b++)phi[a][b]=disturbance[p+a][p+b];var l=new CholeskyDecomposition(new Array2DRowRealMatrix(phi,false),1e-8,1e-12).getL();for(int a=0;a<q;a++){x[betaIndex[a]]=directed[p+q][p+a];for(int b=0;b<=a;b++)x[phiIndex[a][b]]=a==b?Math.log(l.getEntry(a,b)):l.getEntry(a,b);}x[psiIndex]=.5*Math.log(Math.max(.02,disturbance[p+q][p+q]));}}catch(IllegalArgumentException|ArithmeticException invalid){/* fallback is an admissible Gaussian-factor start, not a result */}return x;}
        void errorAt(double[] x,int index,double variance){x[errorIndex[index]]=.5*Math.log(variance);}
        double[] losses(double[] x,Grid grid){State state=decode(x);double[][] covariance=new double[px][px],loading=new double[px][q];for(int a=0;a<px;a++){loading[a][owner[a]]=state.loading[a];for(int b=0;b<px;b++)covariance[a][b]=state.loading[a]*state.loading[b]*state.phi[owner[a]][owner[b]]+(a==b?state.error[a]:0);}var cx=new CholeskyDecomposition(new Array2DRowRealMatrix(covariance,false),1e-9,1e-12);RealMatrix inverse=cx.getSolver().getInverse(),phi=new Array2DRowRealMatrix(state.phi,false),lambda=new Array2DRowRealMatrix(loading,false),gain=phi.multiply(lambda.transpose()).multiply(inverse);double[][] posterior=phi.subtract(gain.multiply(lambda).multiply(phi)).getData();for(int a=0;a<q;a++)for(int b=0;b<a;b++)posterior[a][b]=posterior[b][a]=(posterior[a][b]+posterior[b][a])*.5;RealMatrix aLower=null,conditionalGain=null,conditionalVariance=null;if(integrated.length>0){var aa=sub(posterior,integrated,integrated);var decomposition=new CholeskyDecomposition(aa,1e-8,1e-14);aLower=decomposition.getL();if(analytic.length>0){conditionalGain=sub(posterior,analytic,integrated).multiply(decomposition.getSolver().getInverse());conditionalVariance=sub(posterior,analytic,analytic).subtract(conditionalGain.multiply(sub(posterior,integrated,analytic)));}}else conditionalVariance=new Array2DRowRealMatrix(posterior,false);RealMatrix predictorPrecision=distribution==PredictorDistribution.STUDENT_T?new CholeskyDecomposition(phi,1e-9,1e-12).getSolver().getInverse():null;double importanceConstant=distribution==PredictorDistribution.STUDENT_T?org.apache.commons.math3.special.Gamma.logGamma((degrees+q)/2)-org.apache.commons.math3.special.Gamma.logGamma(degrees/2)+q*.5*Math.log(2/(degrees-2)):0;double logX=px*Math.log(2*Math.PI)+logDet(cx);double measurementLogDet=0,loadingPrecision=0;for(int j=px;j<p;j++){measurementLogDet+=Math.log(state.error[j]);loadingPrecision+=state.loading[j]*state.loading[j]/state.error[j];}double[] output=new double[n],centerX=new double[px],eta=new double[q],coefficients=new double[analytic.length],posteriorMean=new double[q],conditionalMean=new double[analytic.length],sumTerms=new double[grid.values.length];for(int row=0;row<n;row++){if((row&7)==0)Matrices.interrupted();for(int a=0;a<px;a++)centerX[a]=data[row][a]-state.intercept[a];double quadraticX=0;for(int a=0;a<px;a++)for(int b=0;b<px;b++)quadraticX+=centerX[a]*inverse.getEntry(a,b)*centerX[b];for(int a=0;a<q;a++){posteriorMean[a]=0;for(int b=0;b<px;b++)posteriorMean[a]+=gain.getEntry(a,b)*centerX[b];}double maximum=Double.NEGATIVE_INFINITY;for(int node=0;node<grid.values.length;node++){if((node&255)==0)Matrices.interrupted();Arrays.fill(eta,0);for(int a=0;a<integrated.length;a++){double value=posteriorMean[integrated[a]];for(int b=0;b<=a;b++)value+=aLower.getEntry(a,b)*grid.values[node][b];eta[integrated[a]]=value;}for(int a=0;a<analytic.length;a++){conditionalMean[a]=posteriorMean[analytic[a]];if(integrated.length>0)for(int b=0;b<integrated.length;b++)conditionalMean[a]+=conditionalGain.getEntry(a,b)*(eta[integrated[b]]-posteriorMean[integrated[b]]);coefficients[a]=state.beta[analytic[a]];}double conditionalLocation=state.alpha;for(int a:integrated)conditionalLocation+=state.beta[a]*eta[a];for(int t=0;t<state.gamma.length;t++){var interaction=model.interactions().get(t);int ia=-1,ib=-1;for(int b=0;b<analytic.length;b++){if(analytic[b]==interaction.first())ia=b;if(analytic[b]==interaction.second())ib=b;}if(ia>=0)coefficients[ia]+=state.gamma[t]*eta[interaction.second()];else if(ib>=0)coefficients[ib]+=state.gamma[t]*eta[interaction.first()];else conditionalLocation+=state.gamma[t]*eta[interaction.first()]*eta[interaction.second()];}double conditionalError=state.psi;for(int a=0;a<analytic.length;a++){conditionalLocation+=coefficients[a]*conditionalMean[a];for(int b=0;b<analytic.length;b++)conditionalError+=coefficients[a]*conditionalVariance.getEntry(a,b)*coefficients[b];}if(!(conditionalError>0))throw new IllegalArgumentException("Inadmissible conditional latent variance.");double cross=0,quadraticY=0;for(int j=px;j<p;j++){double difference=data[row][j]-state.intercept[j]-state.loading[j]*conditionalLocation;quadraticY+=difference*difference/state.error[j];cross+=state.loading[j]*difference/state.error[j];}double denominator=1+conditionalError*loadingPrecision;double logY=-.5*(py*Math.log(2*Math.PI)+measurementLogDet+Math.log(denominator)+quadraticY-conditionalError*cross*cross/denominator);double importance=0;if(distribution==PredictorDistribution.STUDENT_T){double radius=0;for(int a=0;a<q;a++)for(int b=0;b<q;b++)radius+=eta[a]*predictorPrecision.getEntry(a,b)*eta[b];importance=importanceConstant+.5*radius-(degrees+q)*.5*Math.log1p(radius/(degrees-2));}sumTerms[node]=grid.logWeights[node]+logY+importance;maximum=Math.max(maximum,sumTerms[node]);}double sum=0;for(double term:sumTerms)sum+=Math.exp(term-maximum);output[row]=.5*(logX+quadraticX)-maximum-Math.log(sum);if(!Double.isFinite(output[row]))throw new IllegalArgumentException("Latent likelihood exceeded its finite numeric range.");}return output;}
        double value(double[] x,Grid grid){try{double sum=0;for(double loss:losses(x,grid))sum+=loss;return sum/n;}catch(IllegalArgumentException|ArithmeticException invalid){return Double.POSITIVE_INFINITY;}}
        Bfgs.Evaluation evaluation(double[] x,Grid grid){double value=value(x,grid);if(!Double.isFinite(value))return null;double[] gradient=new double[k];for(int j=0;j<k;j++){double h=1e-5*(1+Math.abs(x[j]));double[] plus=x.clone(),minus=x.clone();plus[j]+=h;minus[j]-=h;double a=value(plus,grid),b=value(minus,grid);if(!Double.isFinite(a)||!Double.isFinite(b))return null;gradient[j]=(a-b)/(2*h);}return new Bfgs.Evaluation(value,gradient);}
        Raw raw(double[] x){State state=decode(x);List<Factor> factors=new ArrayList<>(model.predictors());factors.add(model.outcome());List<Measurement> measurement=new ArrayList<>();double[] loading=new double[p],intercept=new double[p],variance=new double[p];for(int j=0;j<p;j++){loading[j]=scales[j]*state.loading[j]/scales[marker[owner[j]]];intercept[j]=means[j]+scales[j]*state.intercept[j]-(owner[j]==q?loading[j]*means[marker[q]]:0);variance[j]=scales[j]*scales[j]*state.error[j];}for(int j=0;j<factors.size();j++){int start=marker[j],end=j==q?p:marker[j+1];measurement.add(new Measurement(factors.get(j).name(),factors.get(j).columns(),Arrays.copyOfRange(loading,start,end),Arrays.copyOfRange(intercept,start,end),Arrays.copyOfRange(variance,start,end)));}double[][] phi=new double[q][q];for(int a=0;a<q;a++)for(int b=0;b<q;b++)phi[a][b]=state.phi[a][b]*scales[marker[a]]*scales[marker[b]];double outcomeScale=scales[marker[q]],alpha=means[marker[q]]+outcomeScale*state.alpha,psi=outcomeScale*outcomeScale*state.psi;double[] beta=new double[q],gamma=new double[state.gamma.length];for(int j=0;j<q;j++)beta[j]=outcomeScale*state.beta[j]/scales[marker[j]];double mean=alpha;double[][] quadratic=new double[q][q];for(int t=0;t<gamma.length;t++){var term=model.interactions().get(t);int a=term.first(),b=term.second();gamma[t]=outcomeScale*state.gamma[t]/scales[marker[a]]/scales[marker[b]];mean+=gamma[t]*phi[a][b];quadratic[a][b]+=a==b?gamma[t]:gamma[t]/2;if(a!=b)quadratic[b][a]+=gamma[t]/2;}double explained=0;for(int a=0;a<q;a++)for(int b=0;b<q;b++)explained+=beta[a]*phi[a][b]*beta[b];RealMatrix product=new Array2DRowRealMatrix(quadratic,false).multiply(new Array2DRowRealMatrix(phi,false));double fourthMoment=distribution==PredictorDistribution.STUDENT_T?(degrees-2)/(degrees-4):1;explained+=2*fourthMoment*product.multiply(product).getTrace()+(fourthMoment-1)*product.getTrace()*product.getTrace();double latentVariance=explained+psi;List<Double> values=new ArrayList<>();List<String> names=new ArrayList<>();for(int j=0;j<p;j++)if(loadingIndex[j]>=0){values.add(loading[j]);names.add("Loading: "+factors.get(owner[j]).name()+" / column "+factors.get(owner[j]).columns()[j-marker[owner[j]]]);}for(int j=0;j<p;j++)if(interceptIndex[j]>=0){values.add(intercept[j]);names.add("Measurement intercept: column "+factors.get(owner[j]).columns()[j-marker[owner[j]]]);}for(int j=0;j<p;j++){values.add(variance[j]);names.add("Measurement error variance: column "+factors.get(owner[j]).columns()[j-marker[owner[j]]]);}for(int a=0;a<q;a++)for(int b=0;b<=a;b++){values.add(phi[a][b]);names.add("Latent covariance: "+model.predictors().get(a).name()+" / "+model.predictors().get(b).name());}values.add(alpha);names.add("Structural intercept");for(int a=0;a<q;a++){values.add(beta[a]);names.add("Main effect: "+model.predictors().get(a).name());}for(int t=0;t<gamma.length;t++){values.add(gamma[t]);var term=model.interactions().get(t);names.add("Latent product: "+model.predictors().get(term.first()).name()+" * "+model.predictors().get(term.second()).name());}values.add(psi);names.add("Structural residual variance");return new Raw(measurement,phi,alpha,beta,gamma,psi,values.stream().mapToDouble(Double::doubleValue).toArray(),List.copyOf(names),mean,latentVariance,explained/latentVariance);}
    }

    record NumericalProbe(double[] parameters,List<String> labels,double[] means,double[] scales,int dimensions,double logLikelihood,double[] gradient){}
    static NumericalProbe probe(double[][] data,Model model,int nodes,double[] parameters){Work work=new Work(data,model);double[] point=parameters==null?work.initial():parameters.clone();Grid grid=grid(work.integrated.length,nodes);var value=work.evaluation(point,grid);double jacobian=Arrays.stream(work.scales).map(Math::log).sum();return new NumericalProbe(point,work.labels,work.means,work.scales,work.integrated.length,-work.n*(value.value()+jacobian),value.gradient());}
    static NumericalProbe probe(double[][] data,Model model,Options settings,double[] parameters){Work work=new Work(data,model,settings);double[] point=parameters==null?work.initial():parameters.clone();Grid grid=grid(work.integrated.length,settings.nodes());var value=work.evaluation(point,grid);double jacobian=Arrays.stream(work.scales).map(Math::log).sum();return new NumericalProbe(point,work.labels,work.means,work.scales,work.integrated.length,-work.n*(value.value()+jacobian),value.gradient());}
    static double[] impliedMoments(double[][] data,Model model,Options settings,double[] parameters){var work=new Work(data,model,settings);var raw=work.raw(parameters);return new double[]{raw.mean,raw.variance,raw.rSquared};}
    private static double[][] unavailable(int k){double[][] values=new double[k][k];for(var row:values)Arrays.fill(row,Double.NaN);return values;}
    private static Information information(Work work,double[] point,Grid grid,boolean covariance){int k=point.length;double[][] scores=new double[work.n][k],opg=new double[k][k];for(int j=0;j<k;j++){Matrices.interrupted();double h=1e-5*(1+Math.abs(point[j]));double[] plus=point.clone(),minus=point.clone();plus[j]+=h;minus[j]-=h;double[] a=work.losses(plus,grid),b=work.losses(minus,grid);for(int i=0;i<work.n;i++)scores[i][j]=(a[i]-b[i])/(2*h);}for(var row:scores)for(int a=0;a<k;a++)for(int b=0;b<=a;b++)opg[a][b]+=row[a]*row[b]/work.n;for(int a=0;a<k;a++)for(int b=0;b<a;b++)opg[b][a]=opg[a][b];double[][] matrix=opg;if(covariance){matrix=new double[k][k];for(int j=0;j<k;j++){Matrices.interrupted();double h=1e-4*(1+Math.abs(point[j]));double[] plus=point.clone(),minus=point.clone();plus[j]+=h;minus[j]-=h;var a=work.evaluation(plus,grid);var b=work.evaluation(minus,grid);if(a==null||b==null)return new Information(unavailable(k),unavailable(k),0,Double.NaN,false);double[] ga=a.gradient(),gb=b.gradient();for(int i=0;i<k;i++)matrix[i][j]=(ga[i]-gb[i])/(2*h);}for(int a=0;a<k;a++)for(int b=0;b<a;b++)matrix[a][b]=matrix[b][a]=(matrix[a][b]+matrix[b][a])*.5;}double[] scale=new double[k];double[][] normalized=new double[k][k];for(int i=0;i<k;i++){if(!(matrix[i][i]>0)||!Double.isFinite(matrix[i][i]))return new Information(unavailable(k),unavailable(k),0,Double.NaN,false);scale[i]=Math.sqrt(matrix[i][i]);}for(int i=0;i<k;i++)for(int j=0;j<k;j++)normalized[i][j]=matrix[i][j]/scale[i]/scale[j];var eig=new EigenDecomposition(new Array2DRowRealMatrix(normalized,false));double maximum=Arrays.stream(eig.getRealEigenvalues()).max().orElse(0),minimum=Arrays.stream(eig.getRealEigenvalues()).min().orElse(0);int rank=(int)Arrays.stream(eig.getRealEigenvalues()).filter(v->v>maximum*1e-8).count();double condition=minimum>0?maximum/minimum:Double.POSITIVE_INFINITY;if(rank!=k||minimum<=1e-8||condition>1e10)return new Information(unavailable(k),unavailable(k),rank,condition,false);if(!covariance)return new Information(unavailable(k),unavailable(k),rank,condition,true);RealMatrix inverse=new CholeskyDecomposition(new Array2DRowRealMatrix(normalized,false),1e-8,1e-12).getSolver().getInverse();double[][] inv=inverse.getData();for(int i=0;i<k;i++)for(int j=0;j<k;j++)inv[i][j]/=scale[i]*scale[j];RealMatrix bread=new Array2DRowRealMatrix(inv,false);double[][] normal=bread.scalarMultiply(1.0/work.n).getData(),robust=bread.multiply(new Array2DRowRealMatrix(opg,false)).multiply(bread).scalarMultiply(1.0/work.n).getData();double[][] jacobian=new double[k][k];for(int j=0;j<k;j++){double h=1e-5*(1+Math.abs(point[j]));double[] plus=point.clone(),minus=point.clone();plus[j]+=h;minus[j]-=h;double[] a=work.raw(plus).vector,b=work.raw(minus).vector;for(int i=0;i<k;i++)jacobian[i][j]=(a[i]-b[i])/(2*h);}RealMatrix transform=new Array2DRowRealMatrix(jacobian,false);return new Information(transform.multiply(new Array2DRowRealMatrix(normal,false)).multiply(transform.transpose()).getData(),transform.multiply(new Array2DRowRealMatrix(robust,false)).multiply(transform.transpose()).getData(),rank,condition,true);}
    private static Bfgs.Result optimize(Work work,Grid grid,double[] initial,Options settings){return Bfgs.minimize(x->work.evaluation(x,grid),initial,work.lower,work.upper,settings.maxIterations(),settings.gradientTolerance(),settings.functionTolerance());}
    public static Fit fit(double[][] data,Model model,Options settings){return compute(data,model,settings,true);}
    private static Fit compute(double[][] data,Model model,Options settings,boolean covariance){Objects.requireNonNull(settings);Work work=new Work(data,model,settings);Grid low=grid(work.integrated.length,settings.nodes()),high=grid(work.integrated.length,settings.checkNodes());if((long)work.n*high.values.length>1500000)throw new IllegalArgumentException("Latent likelihood quadrature exceeds1.5million case/node evaluations; simplify the model or reduce rows/nodes.");double[] initial=work.initial();Bfgs.Result best=null;List<String>warnings=new ArrayList<>();for(int start=0;start<settings.starts();start++){double[] candidate=initial.clone();if(start>0)for(int j=0;j<work.gammaIndex.length;j++)candidate[work.gammaIndex[j]]=(start%2==0?-.15:.15)*(1+(start-1)/2.0)*(j%2==0?1:-1);for(int j=0;j<candidate.length;j++)candidate[j]=Math.max(work.lower[j]+1e-5,Math.min(work.upper[j]-1e-5,candidate[j]));try{var result=optimize(work,low,candidate,settings);if(best==null||result.evaluation().value()<best.evaluation().value())best=result;}catch(IllegalArgumentException|ArithmeticException invalid){warnings.add("One initialization did not yield a finite admissible optimum.");}}if(best==null)throw new IllegalArgumentException("No finite latent-interaction starting fit was found.");var refined=optimize(work,high,best.point(),settings);double[] point=refined.point(),previous=best.point();double change=0;for(int j=0;j<point.length;j++)change=Math.max(change,Math.abs(point[j]-previous[j])/(1+Math.abs(point[j])));double lossChange=Math.abs(refined.evaluation().value()-best.evaluation().value());boolean stable=best.converged()&&refined.converged()&&change<=settings.integrationTolerance()&&lossChange<=Math.max(1e-7,settings.integrationTolerance()*.01);boolean boundary=false;for(int j=0;j<point.length;j++)if(point[j]-work.lower[j]<1e-4||work.upper[j]-point[j]<1e-4)boundary=true;Information info=information(work,point,high,covariance);boolean identified=info.identified&&!boundary;Raw raw=work.raw(point);double logJacobian=0;for(double value:work.scales)logJacobian+=Math.log(value);double logLikelihood=-work.n*(refined.evaluation().value()+logJacobian);if(!Double.isFinite(logLikelihood)||!Arrays.stream(raw.vector).allMatch(Double::isFinite))throw new IllegalArgumentException("Latent fit cannot be represented finitely in original measurement units.");List<Term> terms=new ArrayList<>();double critical=new NormalDistribution().inverseCumulativeProbability((1+settings.confidence())/2);for(int j=0;j<raw.vector.length;j++){double error=covariance&&identified&&stable&&refined.converged()?Math.sqrt(Math.max(0,info.covariance[j][j])):Double.NaN,robust=covariance&&identified&&stable&&refined.converged()?Math.sqrt(Math.max(0,info.robust[j][j])):Double.NaN;boolean variance=raw.labels.get(j).contains("variance")||raw.labels.get(j).startsWith("Latent covariance");double z=!variance&&error>0?raw.vector[j]/error:Double.NaN,p=Double.isFinite(z)?2*new NormalDistribution().cumulativeProbability(-Math.abs(z)):Double.NaN;terms.add(new Term(raw.labels.get(j),raw.vector[j],error,robust,z,p,raw.vector[j]-critical*error,raw.vector[j]+critical*error));}warnings.add("Independent marginal latent-interaction/quadratic likelihood. Exogenous factors use the declared centered Normal or multivariate Student t distribution; reflective blocks have independent measurement errors, fixed unit marker loadings and one outcome marker intercept fixed to zero. Cross-loadings, correlated measurement errors, ordinal links and additional endogenous latent equations are not silently approximated.");warnings.add(settings.predictorDistribution()==PredictorDistribution.NORMAL?"Normal predictors: condition on predictor indicators, analytically integrate the remaining linear latent part, then use checked Gauss-Hermite integration for the required nonlinear subspace.":"Student t predictors: fixed degrees of freedom >4 define covariance-scaled multivariate t factors. Integrate all latent predictors using a Gaussian conditional-reference importance identity with the exact t/Normal prior-density ratio. There is no Gaussian analytic elimination under this distribution; tail/integration sensitivity must be inspected. Degrees of freedom are fixed, not estimated.");warnings.add("Likelihood includes original-unit scaling; artificial product indicators or fixed factor scores are not used.");warnings.add("Two quadrature levels are optimized and compared. Numerical convergence and integration stability are separate checks; local information rank is a numerical diagnostic, not proof of global identification or a global optimum.");warnings.add("Ordinary covariance-model chi-square/CFI/TLI/RMSEA are not supplied for this non-Gaussian marginal model. AIC/BIC compare matched raw-data likelihood models, subject to assumptions and numerical regularity. R-squared is model-implied latent structural variance explained under the declared centered predictor distribution, including its fourth moments.");warnings.add("Wald ratios use ordinary observed-information SE for regular unbounded nonvariance parameters; sandwich SE is shown separately and is not a robust latent-distribution correction. Case bootstrap refits all measurement/structural parameters. Means, original marker units and preparation must be interpreted explicitly.");if(!refined.converged())warnings.add("Likelihood optimization did not converge; inference is unavailable.");if(!stable)warnings.add("Quadrature/parameter refinement is not stable at the selected orders; increase nodes/check order or simplify before inference.");if(!identified)warnings.add("Information is numerically rank-deficient, ill-conditioned or at a numerical boundary; regular Wald inference is unavailable.");return new Fit(model,settings,work.n,work.k,work.digest,raw.measurement,raw.phi,raw.alpha,raw.beta,raw.gamma,raw.psi,raw.mean,raw.variance,raw.rSquared,logLikelihood,2*work.k-2*logLikelihood,Math.log(work.n)*work.k-2*logLikelihood,refined.converged(),refined.iterations(),refined.reason(),work.integrated.length,stable,change,lossChange,identified,info.rank,info.condition,boundary,terms,covariance&&identified&&stable&&refined.converged()?info.covariance:unavailable(work.k),covariance&&identified&&stable&&refined.converged()?info.robust:unavailable(work.k),point,work.labels,warnings);}
    private static double[] bootstrapValues(Fit fit){double[] values=new double[fit.terms().size()+3];for(int i=0;i<fit.terms().size();i++)values[i]=fit.terms().get(i).estimate();values[values.length-3]=fit.latentOutcomeMean();values[values.length-2]=fit.latentOutcomeVariance();values[values.length-1]=fit.latentRSquared();return values;}
    public static Resampled bootstrap(double[][] data,Model model,Options settings,Bootstrap.Options options,IntConsumer progress){if(options.convention()!=RegressionBootstrap.Convention.STANDARD)throw new IllegalArgumentException("Latent likelihood inference supports standard percentile/genuine BCa, not legacy PLS interval conventions.");Fit point=fit(data,model,settings);if(!point.converged()||!point.integrationStable()||!point.locallyIdentified()||point.boundarySolution())throw new IllegalArgumentException("Latent likelihood inference requires convergence, stable integration and regular full-rank interior information.");List<Bootstrap.Parameter> parameters=new ArrayList<>(point.terms().stream().map(t->new Bootstrap.Parameter("Latent likelihood parameter",-1,-1,-1,t.name())).toList());for(String label:List.of("Latent outcome mean","Latent outcome variance","Latent structural R squared"))parameters.add(new Bootstrap.Parameter("Latent structural derived",-1,-1,-1,label));double[] values=bootstrapValues(point);var result=Resampling.run(data,parameters,values,options,(sample,rows)->{var draw=compute(sample,model,settings,false);if(!draw.converged()||!draw.integrationStable()||!draw.locallyIdentified()||draw.boundarySolution())throw new IllegalArgumentException("Latent likelihood replicate is nonconverged, numerically unstable, unidentified or at a boundary.");return bootstrapValues(draw);},progress,"Gaussian latent-interaction marginal ML","Every original-case/jackknife draw refits all measurement, covariance, mean and structural parameters and repeats quadrature refinement. Unit marker constraints fix factor orientation. No product-indicator or fixed-score uncertainty shortcut is used.");result=Resampling.suppressTests(result,p->p.label().contains("variance")||p.label().startsWith("Latent covariance")||p.family().equals("Latent structural derived"),"Variance/covariance parameters do not receive generic bootstrap ratio tests; empirical intervals remain available.");List<String>warnings=new ArrayList<>(result.warnings());warnings.addAll(point.warnings());return new Resampled(point,new Bootstrap.Result(result.options(),result.method(),result.randomGenerator(),result.signHandling(),result.successful(),result.failed(),result.failures(),result.estimates(),warnings,result.estimator()));}
    public record Comparison(String dataSha256,double statistic,int addedParameters,double pValue,boolean regular,List<String> warnings){public Comparison{warnings=List.copyOf(warnings);}}
    public static Comparison compare(Fit linear,Fit nonlinear){if(linear.options().predictorDistribution()!=nonlinear.options().predictorDistribution()||linear.options().predictorDegreesOfFreedom()!=nonlinear.options().predictorDegreesOfFreedom()||!linear.dataSha256().equals(nonlinear.dataSha256())||linear.observations()!=nonlinear.observations()||!linear.model().interactions().isEmpty()||nonlinear.model().interactions().isEmpty()||linear.model().predictors().size()!=nonlinear.model().predictors().size())throw new IllegalArgumentException("Compare the same observed cases and measurement model against its interaction-free baseline.");List<Factor>a=new ArrayList<>(linear.model().predictors()),b=new ArrayList<>(nonlinear.model().predictors());a.add(linear.model().outcome());b.add(nonlinear.model().outcome());for(int i=0;i<a.size();i++)if(!a.get(i).name().equals(b.get(i).name())||!Arrays.equals(a.get(i).columns(),b.get(i).columns()))throw new IllegalArgumentException("Latent comparison measurement definitions differ.");boolean regular=linear.converged()&&nonlinear.converged()&&linear.integrationStable()&&nonlinear.integrationStable()&&linear.locallyIdentified()&&nonlinear.locallyIdentified()&&!linear.boundarySolution()&&!nonlinear.boundarySolution();double statistic=2*(nonlinear.logLikelihood()-linear.logLikelihood());int df=nonlinear.parameterCount()-linear.parameterCount();if(statistic< -1e-5||df<1)regular=false;statistic=Math.max(0,statistic);double probability=regular?org.apache.commons.math3.special.Gamma.regularizedGammaQ(df*.5,statistic*.5):Double.NaN;return new Comparison(linear.dataSha256(),statistic,df,probability,regular,List.of("Nested interaction-free likelihood comparison uses the same cases/measurement specification and an asymptotic chi-square reference only for regular, converged, integration-stable interior fits. It is not an absolute covariance-model fit test or proof of causation."));}
}
